const BASE='/api';
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let schemaCards=false;
let session=null,refresh=null,D={},family=null,me=null,page='overview',busy=false,version=0,formRequest=null,pendingEntry=null,reportRows=[],reportHeaders=[],reportTitle='';
