const textError=e=>e.message||'Não foi possível concluir a operação.';
async function request(path,config={},auth=true){if(auth){if(!session)throw Error('Entre novamente para continuar.');if(Date.now()>session.expires_at*1000-60000){if(!refresh)refresh=request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token})},false).then(s=>{session=s;session.expires_at=s.expires_at||Date.now()/1000+s.expires_in;}).finally(()=>refresh=null);await refresh;}}let r;try{r=await fetch(BASE+path,{...config,headers:{'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+session.access_token}:{}),...config.headers},signal:AbortSignal.timeout(30000)});}catch{throw Error('Sem confirmação do servidor. Verifique a conexão e tente novamente com os mesmos dados.');}const txt=await r.text();let data;try{data=txt?JSON.parse(txt):null;}catch{data=null;}if(!r.ok){const e=Error(r.status===401?'Sessão expirada ou acesso inválido. Entre novamente.':r.status===403?'Sem permissão para esta operação.':data?.message||data?.msg||data?.error_description||'Não foi possível concluir.');e.status=r.status;throw e;}return data;}
const rpc=(name,data={})=>request('/rest/v1/rpc/'+name,{method:'POST',body:JSON.stringify(data)});
async function all(table,query=''){let list=[];for(let offset=0;;){const part=await request(`/rest/v1/${table}?select=*&${query}&order=id&limit=500&offset=${offset}`);if(!Array.isArray(part))throw Error('Resposta inesperada ao consultar os dados.');list.push(...part);if(part.length<500)return list;offset+=part.length;}}
const save=(table,data,id)=>request('/rest/v1/'+table+(id?`?id=eq.${id}&familia_id=eq.${family.id}`:''),{method:id?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(id?data:{id:crypto.randomUUID(),familia_id:family.id,...data})});
function setBusy(v){busy=v;$('logout').disabled=v;$('close-modal').disabled=v;}
async function load(){const seq=++version;$('global-message').textContent='Atualizando…';await rpc('fin_atualizar_recorrencias');const tables=['familias','pessoas','contas','cartoes','categorias','fin_subcategorias','fin_metas','fin_orcamentos','fin_movimentos','fin_planos','lancamentos'];const values=await Promise.all(tables.map(t=>all(t)));if(seq!==version||!session)return;D=Object.fromEntries(tables.map((t,i)=>[t,values[i]]));me=D.pessoas.find(p=>p.usuario_id===session.user.id);family=D.familias.find(f=>f.id===me?.familia_id);if(!family)throw Error('Não foi possível carregar seu painel. Contate o administrador.');await ensureCategories();try{schemaCards=(await rpc('fin_versao_cartoes'))===2;}catch(e){if(e.status!==404&&!/schema cache|does not exist/.test(e.message))throw e;schemaCards=false;}document.querySelector('.family').textContent='/ '+me.nome;document.body.classList.add('signed-in');$('greeting').textContent=`Olá, ${me.nome}!`;$('global-message').textContent='';render();}
async function boot(){try{await all('fin_planos','limit=1');}catch(e){if(e.status===404||/schema cache|does not exist/.test(e.message)){$('login').hidden=true;$('setup').hidden=false;$('logout').hidden=false;return;}throw e;}await load();$('login').hidden=true;$('setup').hidden=true;$('app').hidden=false;$('logout').hidden=false;}
mountAuth({request,getInvite:()=>invite,onSession:async value=>{session=value;session.expires_at=value.expires_at||Date.now()/1000+value.expires_in;await boot();}});
$('logout').onclick=async()=>{if(busy||chatState.busy)return;const token=session?.access_token;session=null;D={};family=null;me=null;version++;assistantDrafts=[];assistantText='';Object.assign(chatState,{messages:[],queue:[],index:0,saved:[],busy:false,confirm:false,error:null,editField:null,chooseEdit:false});document.querySelector('.family').textContent='/ Seu painel';document.body.classList.remove('signed-in');$('view').innerHTML='';$('app').hidden=true;$('setup').hidden=true;$('login').hidden=false;$('logout').hidden=true;$('modal').close();if(token)try{await request('/auth/v1/logout',{method:'POST',headers:{Authorization:'Bearer '+token}},false);}catch{}};

$('check-setup').onclick=async()=>{$('check-setup').disabled=true;try{await boot();}catch(e){$('setup-message').textContent=textError(e);}finally{$('check-setup').disabled=false;}};
$('close-modal').onclick=()=>{if(!busy)$('modal').close();};$('modal').addEventListener('close',()=>{if(!$('modal').open)$('modal-body').replaceChildren();if(!busy&&family&&page==='overview'&&!$('entry-form'))render();});$('modal').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
$('month').value=today().slice(0,7);$('month').onchange=()=>{if($('month').value)render();};
function modal(title,body){$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-message').textContent='';$('modal').showModal();}
function render(){if(!family)return;$('view').onclick=null;$('view').onkeydown=null;$('schema-notice').innerHTML=schemaCards?'':`<div class="pill-warning">Há uma atualização para ativar datas de compra, confirmação de cobranças e exclusão definitiva. ${button('cards-update','Ativar atualização')}</div>`;$('page-title').textContent=tabs[page];$('nav').innerHTML=Object.entries(tabs).map(([id,name])=>`<button type="button" data-page="${id}" aria-pressed="${page===id}">${navIcon(id)}<span>${name}</span></button>`).join('');({overview:renderOverview,assistant:renderAssistant,entries:renderEntries,cards:renderCards,accounts:renderAccounts,goals:renderGoals,budgets:renderBudgets,reports:renderReports,settings:renderSettings}[page])();}
$('nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b&&!busy&&!chatState.busy){page=b.dataset.page;render();}};
const metric=(name,value,note,dark=false)=>`<article class="metric ${dark?'dark':''}"><span>${name}</span><strong>${money(value)}</strong><small>${note}</small></article>`;
function liveRows(){return D.fin_movimentos.filter(m=>m.status!=='cancelado');}
function monthRows(){return liveRows().filter(m=>purchaseDate(m,D)?.slice(0,7)===$('month').value);}
function statusName(m){if(m.status==='cancelado')return 'Cancelado';if(m.forma==='credito')return creditPosted(m,D)?'Cobrança efetivada':'Previsão de cobrança';if(m.status==='concluido')return m.tipo==='entrada'?'Recebido':'Concluído';return m.data_prevista<today()?'Atrasado':m.tipo==='entrada'?'A receber':'Pendente';}
function movementList(rows){if(!rows.length)return '<div class="empty"><h3>Nenhum lançamento</h3><p>Os registros aparecerão aqui.</p></div>';return rows.sort((a,b)=>(purchaseDate(b,D)||'').localeCompare(purchaseDate(a,D)||'')||b.criado_em.localeCompare(a.criado_em)).map(m=>`<article class="list-card"><div class="listhead"><strong>${escape(m.descricao)} ${m.total_parcelas>1?`<small>${m.ordem}/${m.total_parcelas}</small>`:''}</strong><strong class="${m.tipo==='entrada'?'positive':''}">${money(m.valor)}</strong></div><p>${escape(scope(m.pessoa_id))} · ${escape(typeNames[m.tipo]||m.tipo)} · ${escape(m.forma==='credito'?cardName(m.cartao_id):account(m.conta_id))}${m.destino_id?' → '+escape(account(m.destino_id)):''}<br>${m.forma==='credito'?'Compra em '+labelDate(purchaseDate(m,D))+' · Fatura vence em '+labelDate(m.data_prevista):'Data: '+labelDate(purchaseDate(m,D))}${m.data_realizada?' · Realizado em '+labelDate(m.data_realizada):''} · ${escape(category(m.categoria_id))}${m.tipo==='entrada'&&payerFor(m)?' · Pagador: '+escape(payerFor(m)):''}${m.subcategoria_id?' / '+escape(D.fin_subcategorias.find(s=>s.id===m.subcategoria_id)?.nome):''}</p><div class="flex"><span class="tag ${m.status==='pendente'&&m.data_prevista<today()&&m.forma!=='credito'?'overdue':''}">${statusName(m)}</span><div class="actions">${m.status==='pendente'&&m.forma!=='credito'?button('settle',m.tipo==='entrada'?'Receber':'Confirmar',m.id):''}${button('edit','Editar',m.id)}${button('duplicate','Duplicar',m.id)}${m.status!=='cancelado'?button('cancel','Cancelar',m.id):''}${button('delete','Excluir',m.id,'danger')}${m.forma==='credito'&&m.status!=='cancelado'&&!creditPosted(m,D)?button('charge','Confirmar cobrança',m.id):''}</div></div></article>`).join('');}
function renderOverview(){
 const m=$('month').value,all=liveRows(),rows=all.filter(x=>dashboardPerson==='all'||(x.pessoa_id||'')===dashboardPerson),t=cashTotals(rows,m+'-01',monthEnd(m));
 const bs=balances(D.contas,all,monthEnd(m)<today()?monthEnd(m):today()),total=bs.reduce((s,a)=>s+a.value,0),reserved=reserves(all,monthEnd(m)<today()?monthEnd(m):today()).reduce((s,r)=>s+r.value,0),known=bs.every(a=>a.known);
 const monthExpenses=rows.filter(x=>x.tipo==='saida'&&x.data_prevista.slice(0,7)===m),groups=groupAmounts(monthExpenses,x=>category(x.categoria_id));
 const pending=rows.filter(x=>x.status==='pendente'&&x.forma!=='credito'&&['saida','pagamento_fatura'].includes(x.tipo)&&x.data_prevista.slice(0,7)===m);
 const faturas=invoices(all).filter(g=>g.month===m).reduce((s,g)=>s+Math.max(0,g.remaining-g.planned),0),due=sumValues(pending)+(dashboardPerson==='all'?faturas:0);
 $('view').innerHTML=`<div class="overview-top"><div class="scope-pills"><span>Meu painel financeiro</span></div>${button('compare','Comparar períodos','','outline')}</div><div class="metrics"><article class="metric metric-green"><span>Entradas recebidas</span><strong>${money(t.income)}</strong><small>Recebimentos efetivos no mês</small></article><article class="metric metric-red"><span>Saídas pagas</span><strong>${money(t.expense)}</strong><small>Inclui pagamentos de fatura</small></article><article class="metric metric-blue"><span>Resultado do mês</span><strong>${money(t.income-t.expense)}</strong><small>Entradas menos saídas pagas</small></article><article class="metric metric-amber"><span>${dashboardPerson==='all'?'Contas a pagar':'Despesas pendentes'}</span><strong>${money(due)}</strong><small>${dashboardPerson==='all'?'Inclui faturas em aberto':'Faturas compartilhadas em Contas e cartões'}</small></article></div><div class="balance-strip"><span>Saldo das minhas contas <b>${money(total)}</b></span><span>Reservado para objetivos <b>${money(reserved)}</b></span><span>Saldo livre <b>${money(total-reserved)}</b></span>${!known?'<small>Saldo parcial: cadastre os saldos iniciais.</small>':''}</div>${dashboardPerson!=='all'?'<p class="report-note">O filtro identifica a pessoa do lançamento. Pagamentos de fatura não são divididos pelas compras; saldos e reservas acima são da família.</p>':''}<div class="dashboard-charts"><section class="panel"><div class="sectiontitle"><h2>Entradas e saídas</h2><label class="compact">Histórico<select id="overview-months"><option value="3">3 meses</option><option value="6" selected>6 meses</option><option value="12">12 meses</option></select></label></div><div id="overview-cash"></div></section><section class="panel"><h2>Gastos por categoria</h2><p class="report-note">Despesas e parcelas pelo vencimento, pagas e pendentes.</p>${donut(groups,'overview-category')}</section></div><div class="workspace-grid"><section class="panel"><div class="sectiontitle"><h2>Lançamento rápido</h2>${button('assistant','Por mensagem','','outline')}</div><div id="entry-host"></div></section><section class="panel"><div class="sectiontitle"><h2>Movimentações do mês</h2>${button('refresh','Atualizar')}</div>${movementList(monthRows().filter(x=>dashboardPerson==='all'||(x.pessoa_id||'')===dashboardPerson))}</section></div><section class="panel goals-strip"><div class="sectiontitle"><h2>Seus objetivos</h2>${button('goals','Ver objetivos','','outline')}</div>${D.fin_metas.filter(g=>g.ativa).slice(0,3).map(g=>{const r=reserves(all).filter(r=>r.meta_id===g.id).reduce((s,r)=>s+r.value,0);return `<div class="goal-mini"><b>${escape(g.nome)}</b><span>${money(r)} de ${money(g.valor_alvo)}</span><div class="progress"><div style="width:${Math.max(0,Math.min(100,r/g.valor_alvo*100))}%"></div></div></div>`;}).join('')||'<p>Crie um objetivo e acompanhe quanto já foi reservado.</p>'}</section>`;
 $('view').querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{dashboardPerson=b.dataset.scope;renderOverview();});let ms=[];const draw=()=>{ms=monthsTo(m,Number($('overview-months').value));$('overview-cash').innerHTML=seriesChart(cashSeries(rows,ms),cashKeys,{id:'overview-cash',title:'Entradas e saídas por mês'});};$('overview-months').onchange=draw;draw();
 const drill=e=>{const b=e.target.closest('[data-drill]');if(!b)return;const i=Number(b.dataset.index);let found=[];if(b.dataset.drill==='overview-cash'){const mm=ms[i];found=rows.filter(x=>x.status==='concluido'&&x.data_realizada?.slice(0,7)===mm&&(b.dataset.series==='income'?x.tipo==='entrada':['saida','pagamento_fatura'].includes(x.tipo)&&x.forma!=='credito'));}else if(b.dataset.drill==='overview-category'){const names=i===5?groups.slice(5).map(g=>g.name):[groups[i]?.name];found=monthExpenses.filter(x=>names.includes(category(x.categoria_id)));}else return;modal('Lançamentos do gráfico',movementList([...found]));};$('view').onclick=drill;$('view').onkeydown=e=>{if(e.target.matches('g[data-drill]')&&['Enter',' '].includes(e.key)){e.preventDefault();drill(e);}};entryForm($('entry-host'));
}
function inlineSelect(name,title,options){return '<div class="inline-field">'+select(name,title,options)+'<button type="button" class="quiet inline-add" data-inline-create="'+name+'">+ '+(name==='categoria_id'?'Nova categoria':name==='subcategoria_id'?'Nova subcategoria':'Nova conta')+'</button></div>';}
function entryForm(host,preset={}){formRequest=crypto.randomUUID();pendingEntry=null;host.innerHTML=`<form id="entry-form"><fieldset><div class="fieldgrid">${select('tipo','O que deseja registrar?',dictOpts(typeNames,preset.tipo||'saida'),true)}${input('valor','Valor total / por ocorrência (R$)','text',preset.valor||'','required inputmode="decimal" placeholder="0,00"')}${select('modalidade','Como acontece?',dictOpts({unico:'Uma vez',parcelado:'Parcelado',recorrente:'Recorrente'},preset.modalidade||'unico'))}${input('descricao','Descrição','text',preset.descricao||'','required maxlength="200"',true)}<input type="hidden" name="pessoa_id" value="${escape(preset.pessoa_id??me.id)}">${input('inicio','Data da compra / primeira ocorrência','date',preset.data_prevista||today(),'required')}<div id="entry-dynamic" class="full"></div></div><div id="entry-preview" class="previewbox"></div></fieldset><button class="primary fullwidth" id="entry-save">Salvar lançamento</button><p id="entry-message" role="status"></p></form>`;const f=$('entry-form');f.dataset.preset=JSON.stringify(preset);f.dataset.autoInvoice=preset.fatura_mes?'false':'true';f.addEventListener('change',e=>{if(['tipo','modalidade'].includes(e.target.name))entryDynamic();else if(['forma','cartao_id','categoria_id'].includes(e.target.name)){if(e.target.name==='cartao_id')f.dataset.autoInvoice='true';entryDynamic(true);}if(e.target.name==='fatura_mes')f.dataset.autoInvoice='false';if(e.target.name==='inicio'){syncInvoice();if(f.elements.status?.value==='concluido'&&e.target.value>today())f.elements.status.value='pendente';if(f.elements.data_realizada)f.elements.data_realizada.value=e.target.value;}previewEntry();});f.addEventListener('input',previewEntry);entryDynamic();previewEntry();f.addEventListener('click',async e=>{const b=e.target.closest('[data-inline-create]');if(!b||busy)return;e.preventDefault();const kind=b.dataset.inlineCreate;if(kind==='subcategoria_id'&&!f.elements.categoria_id?.value){$('entry-message').textContent='Selecione ou crie a categoria principal primeiro.';return;}b.disabled=true;try{const row=await createInlineRecord({kind,type:f.elements.tipo.value,parent:f.elements.categoria_id?.value,accountType:f.elements.forma?.value==='dinheiro'?'dinheiro':'bancaria',getData:()=>D,save});if(row&&f.isConnected){const target=f.elements[kind];const option=document.createElement('option');option.value=row.id;option.textContent=row.nome;target.append(option);target.value=row.id;entryDynamic(true);previewEntry();$('entry-message').textContent='Cadastro selecionado. Continue seu lançamento.';}}finally{if(b.isConnected)b.disabled=false;}});f.onsubmit=submitEntry;}
function entryDynamic(keep=false){const f=$('entry-form'),v=Object.fromEntries(new FormData(f)),preset=JSON.parse(f.dataset.preset||'{}'),data={...preset,...v},type=v.tipo,mode=v.modalidade,normal=['entrada','saida'].includes(type),transfer=['transferencia','aporte','resgate'].includes(type),credit=type==='saida'&&data.forma==='credito',investment=['aporte','resgate','rendimento','perda'].includes(type);let html='';if(normal){html+=inlineSelect('categoria_id',type==='entrada'?'Receita de quê?':'Categoria',opts(D.categorias.filter(c=>c.ativa&&c.tipo===type),data.categoria_id,'Selecione'));html+='<details class="full entry-extra"'+(data.subcategoria_id?' open':'')+'><summary>Subcategoria (opcional)</summary>'+inlineSelect('subcategoria_id','Subcategoria',opts(D.fin_subcategorias.filter(s=>s.categoria_id===data.categoria_id),data.subcategoria_id,'Sem subcategoria'))+'</details>';if(type==='entrada')html+='<details class="full entry-extra"><summary>Quem pagou? (opcional)</summary>'+input('pagador','Quem pagou? (opcional)','text',data.pagador||'','maxlength=100 placeholder="Empresa ou cliente"',true)+'</details>';html+=select('forma','Forma',dictOpts(Object.fromEntries(Object.entries(methods).filter(([k])=>type==='saida'||k!=='credito')),data.forma||'pix'));}else html+='<input type="hidden" name="forma" value="transferencia">';
if(credit||type==='pagamento_fatura'){html+=select('cartao_id','Cartão',opts(D.cartoes.filter(c=>c.ativo),data.cartao_id||(D.cartoes.filter(c=>c.ativo).length===1?D.cartoes.find(c=>c.ativo).id:''),'Selecione'));const card=D.cartoes.find(c=>c.id===(data.cartao_id||(D.cartoes.filter(c=>c.ativo).length===1?D.cartoes.find(c=>c.ativo).id:'')));const fm=type==='pagamento_fatura'?data.fatura_mes?.slice(0,7)||'':f.dataset.autoInvoice==='false'?data.fatura_mes?.slice(0,7)||firstInvoice(v.inicio,card):firstInvoice(v.inicio,card);html+=input('fatura_mes',type==='pagamento_fatura'?'Fatura que está pagando':'Primeira fatura (ajustável)','month',fm,'required');if(credit&&!card?.dia_vencimento)html+='<p class="full pill-warning">Configure o fechamento e vencimento do cartão antes de salvar.</p>';}
if(!credit){const source=D.contas.filter(a=>a.ativa&&(data.forma==='dinheiro'?a.tipo==='dinheiro':true));html+=inlineSelect('conta_id',transfer?'Conta de origem':'Conta',opts(source,data.conta_id||(source.length===1?source[0].id:''),'Selecione'));}if(transfer){html+=inlineSelect('destino_id','Conta de destino',opts(D.contas.filter(a=>a.ativa),data.destino_id,'Selecione'));}if(investment||['reserva','liberacao'].includes(type)){html+=select('meta_id',['reserva','liberacao'].includes(type)?'Objetivo':'Objetivo (opcional)',opts(D.fin_metas.filter(x=>x.ativa),data.meta_id,'Sem objetivo'));}
if(mode==='parcelado')html+=input('quantidade','Número de parcelas','number',data.quantidade||2,'min="2" max="600" step="1" required');if(mode!=='unico'){html+=select('frequencia','Intervalo',dictOpts(credit?(mode==='parcelado'?{mensal:'Mensal'}:{mensal:'Mensal',trimestral:'Trimestral',anual:'Anual'}):frequencies,credit&&mode==='parcelado'?'mensal':data.frequencia||'mensal'));if(mode==='recorrente')html+=input('fim','Repetir até (opcional)','date',data.fim||'');}if(!credit){html+=select('status','Situação da primeira ocorrência',dictOpts({pendente:type==='entrada'?'A receber':'Pendente',concluido:type==='entrada'?'Já recebido':'Já realizado'},data.status||(v.inicio<=today()?'concluido':'pendente')));html+='<details class="full entry-extra"><summary>Alterar data efetiva</summary>'+input('data_realizada','Data efetiva (se já realizado)','date',data.data_realizada||v.inicio,`max="${today()}"`)+'</details>';}else html+='<input type="hidden" name="status" value="pendente">';$('entry-dynamic').innerHTML='<div class="fieldgrid">'+html+'</div>';}
function parseValue(v){const s=String(v).trim();if(!/^\d+(?:[,.]\d{1,2})?$/.test(s))throw Error('Informe o valor sem separador de milhar, por exemplo 1250,50.');const n=Number(s.replace(',','.'));if(n<=0||n>999999999999.99)throw Error('Informe um valor maior que zero.');return n;}
function syncInvoice(){const f=$('entry-form');if(f?.elements.forma?.value==='credito'&&f.dataset.autoInvoice!=='false'&&f.elements.fatura_mes)f.elements.fatura_mes.value=firstInvoice(f.elements.inicio.value,D.cartoes.find(c=>c.id===f.elements.cartao_id?.value));}
function previewEntry(){const f=$('entry-form');if(!f)return;syncInvoice();const v=Object.fromEntries(new FormData(f));let n;try{n=parseValue(v.valor);}catch{$('entry-preview').textContent='Preencha o lançamento. Confira as datas antes de salvar.';return;}if(!v.inicio)return;const count=v.modalidade==='parcelado'?Math.max(1,Math.min(600,Number(v.quantidade)||1)):v.modalidade==='recorrente'?3:1,vs=v.modalidade==='parcelado'?parts(n,count):Array(count).fill(n),card=D.cartoes.find(c=>c.id===v.cartao_id),credit=v.forma==='credito';let lines=[];for(let i=0;i<Math.min(count,12);i++){const occurrence=recurringDate(v.inicio,i,v.frequencia||'mensal');if(v.fim&&occurrence>v.fim)break;let d=occurrence;if(credit&&v.fatura_mes&&card?.dia_vencimento){const step=v.modalidade==='parcelado'?i:i*(v.frequencia==='anual'?12:v.frequencia==='trimestral'?3:1);d=dayInMonth(monthShift(v.fatura_mes,step),card.dia_vencimento);}lines.push(`${v.modalidade==='parcelado'?`${i+1}/${count} · `:''}${credit?'Cobrança '+labelDate(occurrence)+' · Fatura vence ':''}${labelDate(d)} · ${money(vs[i])}`);}if(v.modalidade==='recorrente')lines.push(`Repete: ${frequencies[v.frequencia]||'Mensal'}${v.fim?' até '+labelDate(v.fim):' sem término definido'}. O dia original é mantido, usando o último dia nos meses mais curtos.`);if(credit)lines.push('Compras no dia do fechamento são sugeridas para a próxima fatura. Você pode ajustar a primeira fatura.');$('entry-preview').innerHTML=lines.map(escape).join('<br>')+(count>12?`<br>… ${count} parcelas no total.`:'');}
function reserveCheck(v,amount){if(!v.meta_id||v.status!=='concluido')return;const rs=reserves(liveRows());const acc=v.tipo==='aporte'?v.destino_id:v.conta_id;const existing=rs.filter(x=>x.meta_id===v.meta_id&&x.conta_id===acc).reduce((s,x)=>s+x.value,0);if(['resgate','liberacao'].includes(v.tipo)&&amount>existing+.001)throw Error('O valor excede a reserva deste objetivo nesta conta.');if(v.tipo==='reserva'){const b=balances(D.contas,liveRows()).find(a=>a.id===acc);if(!b?.known)throw Error('Cadastre o saldo inicial da conta antes de reservar.');const used=rs.filter(x=>x.conta_id===acc).reduce((s,x)=>s+x.value,0);if(amount>b.value-used+.001)throw Error('Não há saldo livre suficiente nesta conta para a reserva.');}}
async function submitEntry(e){e.preventDefault();if(busy)return;const f=e.target,v=pendingEntry?.values||Object.fromEntries(new FormData(f)),msg=$('entry-message');try{if(v.pessoa_id==='__choose'||v.forma==='__choose')throw Error('Escolha de quem é o lançamento e a forma de pagamento.');const amount=parseValue(v.valor),credit=v.forma==='credito';if(['entrada','saida'].includes(v.tipo)&&!v.categoria_id)throw Error('Selecione a categoria.');if(!credit&&!v.conta_id)throw Error('Selecione a conta.');if(['transferencia','aporte','resgate'].includes(v.tipo)&&(!v.destino_id||v.destino_id===v.conta_id))throw Error('Escolha contas de origem e destino diferentes.');if(['reserva','liberacao'].includes(v.tipo)&&!v.meta_id)throw Error('Escolha o objetivo.');if((credit||v.tipo==='pagamento_fatura')&&(!v.cartao_id||!v.fatura_mes))throw Error('Escolha o cartão e a fatura.');if(credit&&!D.cartoes.find(c=>c.id===v.cartao_id)?.dia_vencimento)throw Error('Configure as datas do cartão.');if(v.status==='concluido'&&(!v.data_realizada||v.data_realizada>today()))throw Error('Confira a data efetiva; eventos futuros devem ficar pendentes.');if(v.modalidade==='parcelado'&&cents(amount)<Number(v.quantidade))throw Error('O valor não permite tantas parcelas.');reserveCheck(v,amount);const body={...v,valor:amount,forma:v.forma||'transferencia',conta_id:credit?null:v.conta_id||null,cartao_id:credit||v.tipo==='pagamento_fatura'?v.cartao_id:null,fatura_mes:v.fatura_mes?v.fatura_mes+'-01':null};pendingEntry={values:v};setBusy(true);f.querySelector('fieldset').disabled=true;$('entry-save').disabled=true;msg.textContent='Salvando…';await rpc('fin_criar',{p_id:formRequest,p_familia:family.id,p_modalidade:v.modalidade,p_inicio:v.inicio,p_fim:v.fim||null,p_frequencia:credit&&v.modalidade==='parcelado'?'mensal':v.frequencia||'mensal',p_quantidade:v.modalidade==='parcelado'?Number(v.quantidade):1,p_dados:body});pendingEntry=null;const preset=JSON.parse(f.dataset.preset||'{}');if(preset.__assistant&&assistantDrafts[preset.__index])assistantDrafts[preset.__index].saved=true;$('modal').close();await load();$('global-message').textContent='Lançamento salvo. As parcelas e recorrências já foram organizadas.';}catch(err){msg.textContent=textError(err);if(f.isConnected){const uncertain=pendingEntry&&!err.status;f.querySelector('fieldset').disabled=!!uncertain;if(!uncertain)pendingEntry=null;const b=$('entry-save');if(b){b.disabled=false;b.textContent=uncertain?'Verificar envio e tentar novamente':'Salvar lançamento';}}}finally{setBusy(false);}}
function renderEntries(){const m=$('month').value;$('view').innerHTML=`<div class="toolbar">${button('new','Novo lançamento','','primary')}${button('refresh','Atualizar')}</div><div class="panel"><div class="filters">${input('search','Buscar descrição','search','','id="filter-search"')}${select('who','De quem é?',`<option value="all">Todos</option>${scopeOptions('')}`)}${select('state','Situação',dictOpts({all:'Todas',pendente:'Pendente',concluido:'Concluído',cancelado:'Cancelado'},'all'))}${select('category','Categoria',opts(D.categorias,'','Todas'))}${select('account','Conta',opts(D.contas,'','Todas'))}${select('card','Cartão',opts(D.cartoes,'','Todos'))}${input('from','De','date',m+'-01')}${input('to','Até','date',monthEnd(m))}</div><div id="filtered-list"></div></div>`;document.querySelectorAll('.filters input,.filters select').forEach(el=>el.addEventListener('input',filterEntries));filterEntries();}
function filterEntries(){const root=document.querySelector('.filters'),v=Object.fromEntries([...root.querySelectorAll('input,select')].map(e=>[e.name,e.value]));const rows=D.fin_movimentos.filter(m=>(!v.search||m.descricao.toLocaleLowerCase().includes(v.search.toLocaleLowerCase()))&&(v.who==='all'||(m.pessoa_id||'')===v.who)&&(v.state==='all'||m.status===v.state)&&(!v.category||m.categoria_id===v.category)&&(!v.account||m.conta_id===v.account||m.destino_id===v.account)&&(!v.card||m.cartao_id===v.card)&&(!v.from||(purchaseDate(m,D)||'')>=v.from)&&(!v.to||(purchaseDate(m,D)||'')<=v.to));$('filtered-list').innerHTML=`<p class="small">${rows.length} registro(s)</p>`+movementList(rows);}
function renderAccounts(){const bs=balances(D.contas,liveRows()),rs=reserves(liveRows());$('view').innerHTML=`<div class="toolbar">${button('account-new','Adicionar conta','','primary')}${button('transfer','Transferir')}${button('refresh','Atualizar')}</div><p class="notice">O saldo inicial representa o início do dia informado. Movimentações realizadas nessa data ou depois dela serão somadas. Sem saldo inicial, o resultado é apenas a movimentação registrada.</p><div class="data-grid">${bs.map(a=>{const reserved=rs.filter(r=>r.conta_id===a.id).reduce((s,r)=>s+r.value,0);return `<section class="panel"><h3>${escape(a.nome)}</h3><span class="tag">${escape(a.tipo)}</span><div class="bigvalue">${money(a.value)}</div><p class="small">${a.known?'Saldo calculado':'Movimentação parcial — saldo inicial não cadastrado'}</p><p>Reservado: ${money(reserved)}<br>Livre: ${money(a.value-reserved)}</p><div class="actions">${button('account-edit','Configurar',a.id)}${button('reconcile','Conferir saldo',a.id)}${button('account-statement','Extrato',a.id)}</div></section>`;}).join('')}</div>`;}
function showCardsUpdate(){modal('Atualização necessária','<p>Peça ao administrador para verificar as migrações do banco no EasyPanel e reiniciar a aplicação.</p>'+button('verify-cards','Verificar atualização'));}
function renderCards(){
 const month=$('month').value,summary=cardSummary(D,month),total=k=>summary.reduce((s,c)=>s+c[k],0),all=total('gross'),actual=total('actual'),predicted=total('projected'),paid=total('paid'),remaining=total('remaining');
 $('view').innerHTML=`<div class="toolbar">${button('card-new','Adicionar cartão','','primary')}${button('new-credit','Compra no crédito')}${button('pay-invoice','Pagar fatura')}</div><div class="cards-month"><div><span class="eyebrow">FATURAS COM VENCIMENTO EM</span><h2>${escape(monthName(month))}</h2></div><strong>${money(all)}<small>Total dos cartões · inclui previsões</small></strong></div><div class="metrics"><article class="metric metric-blue"><span>Cobranças efetivadas</span><strong>${money(actual)}</strong></article><article class="metric metric-amber"><span>Recorrências e compras previstas</span><strong>${money(predicted)}</strong></article><article class="metric metric-green"><span>Já pago</span><strong>${money(paid)}</strong></article><article class="metric metric-red"><span>Restante previsto a pagar</span><strong>${money(remaining)}</strong></article></div><section class="panel"><h2>Comparativo entre cartões</h2><p class="report-note">Toque em uma barra para ver as compras da fatura. Os valores acompanham o mês selecionado.</p>${seriesChart(summary.map(c=>({label:c.nome,actual:c.actual,projected:c.projected})),[{key:'actual',name:'Efetivadas',color:'var(--north-secondary)'},{key:'projected',name:'Previstas',color:'var(--north-amber)'}],{id:'card-dashboard',title:'Faturas por cartão'})}</section><div class="data-grid cards-grid">${summary.map((c,i)=>`<section class="panel card-dashboard"><div class="sectiontitle"><h3>${escape(c.nome)}</h3><span class="tag">${c.dueKnown?'Vence em '+labelDate(c.due):'Configure o vencimento'}</span></div><div class="bigvalue">${money(c.gross)}</div><p>Cobrado: <b>${money(c.actual)}</b><br>Previsto: <b>${money(c.projected)}</b><br>Pago: <b>${money(c.paid)}</b></p><div class="card-remaining">Restante previsto <strong>${money(c.remaining)}</strong></div>${c.excess?`<p class="pill-warning">Pagamento excede as compras registradas em ${money(c.excess)}. Confira a fatura.</p>`:''}<details><summary>Limite estimado do cartão hoje</summary><p>Comprometido: ${money(c.committed)}<br>${c.limite===null||c.limite===undefined?'Limite não cadastrado':'Limite: '+money(c.limite)+'<br>Disponível: '+money(c.available)}</p><p class="small">Inclui parcelas em aberto de compras efetivadas. Recorrências ainda previstas não reduzem o limite.</p></details><div class="actions"><button class="quiet" data-card-detail="${i}">Ver compras</button>${c.remaining>0?button('pay-specific','Pagar fatura',c.cartao_id+'|'+month,'primary'):''}${button('card-edit','Configurar',c.cartao_id)}</div></section>`).join('')}</div><p class="notice">Dados registrados no painel, sem sincronização com o banco. Confirme a cobrança quando a assinatura aparecer no cartão; previsão não significa cobrança efetivada. O limite estimado considera todos os meses, enquanto os totais acima consideram somente ${escape(monthName(month))}.</p>`;
 const open=i=>{const c=summary[i];if(c)modal(c.nome+' · '+monthName(month),`<p>Vencimento: ${labelDate(c.due)} · Total: ${money(c.gross)}</p>`+movementList([...c.items]));};$('view').onclick=e=>{const b=e.target.closest('[data-card-detail],[data-drill="card-dashboard"]');if(b)open(Number(b.dataset.cardDetail??b.dataset.index));};$('view').onkeydown=e=>{if(e.target.matches('[data-drill="card-dashboard"]')&&['Enter',' '].includes(e.key)){e.preventDefault();open(Number(e.target.dataset.index));}};
}
function renderGoals(){const rs=reserves(liveRows()),bs=balances(D.contas,liveRows());$('view').innerHTML=`<div class="toolbar">${button('goal-new','Criar objetivo','','primary')}${button('invest','Registrar aporte')}${button('reserve','Reservar sem transferir')}${button('redeem','Resgatar / retirar')}</div><p class="notice">Aporte movimenta dinheiro entre contas. Reserva apenas destina um saldo já existente a um objetivo. Rendimentos e perdas são informados separadamente. Nenhuma dessas operações cria uma despesa de consumo.</p><div class="data-grid">${D.fin_metas.filter(g=>g.ativa).map(g=>{const saved=rs.filter(r=>r.meta_id===g.id).reduce((s,r)=>s+r.value,0),pct=Math.min(100,Math.max(0,saved/Number(g.valor_alvo)*100)),remaining=Math.max(0,Number(g.valor_alvo)-saved);let monthly='';if(g.prazo&&g.prazo>=today()){const [y,m]=g.prazo.split('-').map(Number),[cy,cm]=today().split('-').map(Number),months=Math.max(1,(y-cy)*12+m-cm+1);monthly=`<p class="small">Para atingir no prazo: ${money(remaining/months)} por mês, sem supor rendimentos.</p>`;}return `<section class="panel"><h3>${escape(g.nome)}</h3><span class="tag">${escape(scope(g.pessoa_id))}</span><div class="bigvalue">${money(saved)}</div><p>Meta: ${money(g.valor_alvo)} · ${pct.toFixed(0)}%</p><div class="progress"><div style="width:${pct}%"></div></div><p>Faltam ${money(remaining)}${g.prazo?'<br>Prazo: '+labelDate(g.prazo):''}</p>${monthly}<p class="small">${rs.filter(r=>r.meta_id===g.id&&r.value!==0).map(r=>escape(account(r.conta_id))+': '+money(r.value)).join('<br>')||'Ainda sem reservas.'}</p><div class="actions">${button('goal-add','Adicionar valor',g.id)}${button('goal-release','Liberar reserva',g.id)}${button('goal-edit','Editar',g.id)}</div></section>`;}).join('')||'<section class="panel"><p>Crie um objetivo para acompanhar o progresso.</p></section>'}</div><section class="panel" style="margin-top:24px"><h2>Poupança e investimentos</h2>${bs.filter(a=>['poupanca','investimento'].includes(a.tipo)).map(a=>`<div class="invoice-row"><span>${escape(a.nome)} ${!a.known?'(saldo parcial)':''}</span><strong>${money(a.value)}</strong></div>`).join('')||'<p>Cadastre a poupança ou investimento como uma conta para registrar aplicações.</p>'}<div class="actions">${button('investment-account','Cadastrar investimento')}${button('yield','Informar rendimento')}${button('loss','Informar perda')}</div></section>`;}
function expensesMonth(m){return liveRows().filter(x=>x.tipo==='saida'&&x.data_prevista.slice(0,7)===m);}
function renderBudgets(){const m=$('month').value,ex=expensesMonth(m);$('view').innerHTML=`<div class="toolbar">${button('budget-new','Definir orçamento','','primary')}</div><p class="notice">O comprometido inclui despesas pagas e pendentes, inclusive parcelas de cartão com vencimento no mês. Pagamentos de fatura não são somados novamente.</p><div class="data-grid">${D.fin_orcamentos.filter(b=>b.mes.slice(0,7)===m).map(b=>{const used=ex.filter(x=>x.categoria_id===b.categoria_id).reduce((s,x)=>s+cents(x.valor),0)/100;return `<section class="panel"><h3>${escape(category(b.categoria_id))}</h3><div class="bigvalue">${money(used)}</div><p>Orçamento: ${money(b.valor)}<br>${used>Number(b.valor)?'Excedido em':'Disponível'}: ${money(Math.abs(Number(b.valor)-used))}</p><div class="progress"><div style="width:${Math.min(100,used/Number(b.valor)*100)}%"></div></div>${button('budget-edit','Ajustar',b.id)}</section>`;}).join('')||'<section class="panel"><p>Nenhum orçamento definido neste mês.</p></section>'}</div>`;}
function renderSettings(){$('view').innerHTML=`<section class="panel"><h2>Meu acesso</h2><p><strong>${escape(me.nome)}</strong></p><p class="small">Seus cadastros e lançamentos ficam no seu painel. Novos usuários criam contas independentes pela tela inicial.</p></section><div class="workspace-grid"><section class="panel"><div class="sectiontitle"><h2>Categorias e fontes de receitas</h2>${button('category-new','Adicionar')}</div>${D.categorias.map(c=>`<div class="list-card"><b>${escape(c.nome)}</b><span class="small"> · ${c.tipo==='entrada'?'Entrada':'Despesa'}</span><div class="actions">${button('category-edit','Editar',c.id)}${button('subcategory-new','Subcategoria',c.id)}</div><p class="small">${D.fin_subcategorias.filter(s=>s.categoria_id===c.id).map(s=>escape(s.nome)+' '+button('subcategory-edit','Editar',s.id)).join('<br>')||'Sem subcategorias'}</p></div>`).join('')}</section><section class="panel"><h2>Como interpretar os números</h2><p><b>Saídas pagas:</b> dinheiro que saiu para despesas e faturas.</p><p><b>Gastos e compromissos:</b> despesas e parcelas por vencimento, sem duplicar pagamentos de fatura.</p><p><b>Saldo:</b> saldo inicial mais movimentações efetivas.</p><p><b>Reservas:</b> parte do saldo destinada a objetivos; não é um saldo adicional.</p><p><b>Investimentos:</b> valores informados manualmente, sem conexão automática com bancos.</p><p><b>Recorrências:</b> próximas ocorrências são preparadas até 24 meses à frente quando o painel é acessado.</p></section></div>`;}
function simpleForm(fields,buttonText='Salvar'){return `<form id="simple-form"><fieldset><div class="fieldgrid">${fields}</div></fieldset><button class="primary">${buttonText}</button></form>`;}
function bindSimple(fn){$('simple-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=e.target,v=Object.fromEntries(new FormData(f));setBusy(true);f.querySelector('fieldset').disabled=true;f.querySelector('button').disabled=true;try{await fn(v);$('modal').close();await load();$('global-message').textContent='Alteração salva.';}catch(err){$('modal-message').textContent=textError(err);if(f.isConnected){f.querySelector('fieldset').disabled=false;f.querySelector('button').disabled=false;}}finally{setBusy(false);}};}
function configAccount(id='',presetType='bancaria'){const a=D.contas.find(x=>x.id===id)||{};modal(id?'Configurar conta':'Nova conta',simpleForm(input('nome','Nome','text',a.nome||'','required',true)+select('tipo','Tipo',dictOpts({bancaria:'Conta bancária',dinheiro:'Dinheiro',poupanca:'Poupança',investimento:'Investimento'},a.tipo||presetType))+input('saldo','Saldo inicial (pode ser negativo)','text',a.saldo_inicial??'','inputmode="decimal"')+input('data','Data do saldo inicial','date',a.data_saldo_inicial||'')+'<p class="full small">Saldo no início do dia. Não registre como saldo inicial um valor que já inclua os lançamentos desse dia.</p>'));bindSimple(async v=>{let val=null;if(v.saldo.trim()){if(!/^-?\d+([,.]\d{1,2})?$/.test(v.saldo))throw Error('Saldo inválido. Use 1234,56 sem separador de milhar.');val=Number(v.saldo.replace(',','.'));if(!v.data)throw Error('Informe a data do saldo inicial.');}await save('contas',{nome:v.nome.trim(),tipo:v.tipo,saldo_inicial:val,data_saldo_inicial:val===null?null:v.data},id);});}
function configCard(id=''){const c=D.cartoes.find(x=>x.id===id)||{};modal(id?'Configurar cartão':'Novo cartão',simpleForm(input('nome','Nome','text',c.nome||'','required',true)+input('fecha','Dia de fechamento','number',c.dia_fechamento||'','min="1" max="31" required')+input('vence','Dia de vencimento','number',c.dia_vencimento||'','min="1" max="31" required')+input('limite','Limite (opcional)','text',c.limite??'','inputmode="decimal"',true)+'<p class="full small">As datas novas serão usadas nos próximos lançamentos. Parcelas já cadastradas mantêm o vencimento original.</p>'));bindSimple(v=>save('cartoes',{nome:v.nome.trim(),dia_fechamento:Number(v.fecha),dia_vencimento:Number(v.vence),limite:v.limite.trim()?parseValue(v.limite):null},id));}
function configGoal(id=''){const g=D.fin_metas.find(x=>x.id===id)||{};modal(id?'Editar objetivo':'Novo objetivo',simpleForm(input('nome','Nome','text',g.nome||'','required',true)+input('valor','Valor da meta','text',g.valor_alvo||'','required inputmode="decimal"')+select('pessoa_id','De quem é?',scopeOptions(g.pessoa_id))+input('prazo','Prazo (opcional)','date',g.prazo||'')+'<p class="full small">Para informar dinheiro já guardado, crie a meta e depois use “Reservar sem transferir” na conta onde ele está.</p>'));bindSimple(v=>save('fin_metas',{nome:v.nome.trim(),valor_alvo:parseValue(v.valor),pessoa_id:v.pessoa_id||null,prazo:v.prazo||null},id));}
function configBudget(id=''){const b=D.fin_orcamentos.find(x=>x.id===id)||{};modal('Orçamento por categoria',simpleForm(select('categoria_id','Categoria',opts(D.categorias.filter(c=>c.tipo==='saida'),b.categoria_id))+input('mes','Mês','month',b.mes?.slice(0,7)||$('month').value,'required')+input('valor','Limite planejado','text',b.valor||'','required inputmode="decimal"',true)));bindSimple(async v=>{const existing=D.fin_orcamentos.find(x=>x.categoria_id===v.categoria_id&&x.mes===v.mes+'-01');await save('fin_orcamentos',{categoria_id:v.categoria_id,mes:v.mes+'-01',valor:parseValue(v.valor)},id||existing?.id);});}
function configCategory(id='',parent='',sub=false){const c=(sub?D.fin_subcategorias:D.categorias).find(x=>x.id===id)||{};modal(sub?'Subcategoria':'Categoria',simpleForm(input('nome','Nome','text',c.nome||'','required',true)+(sub?select('categoria_id','Categoria principal',opts(D.categorias,c.categoria_id||parent),true):select('tipo','Tipo',dictOpts(id?{[c.tipo]:c.tipo==='saida'?'Despesa':'Entrada'}:{saida:'Despesa',entrada:'Entrada'},c.tipo||'saida'),true))));bindSimple(v=>save(sub?'fin_subcategorias':'categorias',sub?{nome:v.nome.trim(),categoria_id:v.categoria_id}:{nome:v.nome.trim(),tipo:v.tipo},id));}
const reports={resumo:'Resumo financeiro',categorias:'Gastos por categoria',pessoas:'Responsável pelo lançamento',faturas:'Faturas e parcelas',vencimentos:'Contas a pagar e receber',projecao:'Projeção de saldo',orcamento:'Orçamento × comprometido',extrato:'Extrato por conta',objetivos:'Objetivos e reservas',investimentos:'Aportes e investimentos'};let reportRecords=[];
function renderDetailedReports(){const m=$('month').value;$('view').innerHTML=`<section class="panel report-screen"><div class="filters">${select('report','Relatório',dictOpts(reports,'resumo'))}${input('start','De','date',m+'-01')}${input('end','Até','date',monthEnd(m))}${select('person','De quem é?',`<option value="all">Todos</option>${scopeOptions('')}`)}${select('cat','Categoria',opts(D.categorias,'','Todas'))}${select('acc','Conta',opts(D.contas,'','Todas'))}${select('card','Cartão',opts(D.cartoes,'','Todos'))}</div><div class="toolbar">${button('csv','Baixar planilha (CSV)')}${button('print','Imprimir / salvar PDF')}${button('report-detail','Ver lançamentos filtrados')}</div><h2 id="report-title"></h2><p id="report-note" class="report-note"></p><div id="report-charts"></div><div class="tablewrap"><table class="report-table"><thead id="report-head"></thead><tbody id="report-body"></tbody></table></div></section>`;document.querySelectorAll('.filters input,.filters select').forEach(e=>e.onchange=updateReport);updateReport();}
function updateReport(){const root=document.querySelector('.filters');if(!root)return;const v=Object.fromEntries([...root.querySelectorAll('input,select')].map(e=>[e.name,e.value]));if(!v.start||!v.end||v.start>v.end){$('report-note').textContent='Escolha um intervalo válido.';return;}const base=liveRows().filter(x=>(v.person==='all'||(x.pessoa_id||'')===v.person)&&(!v.cat||x.categoria_id===v.cat)&&(!v.acc||x.conta_id===v.acc||x.destino_id===v.acc)&&(!v.card||x.cartao_id===v.card));const period=base.filter(x=>x.data_prevista>=v.start&&x.data_prevista<=v.end),done=base.filter(x=>x.status==='concluido'&&x.data_realizada>=v.start&&x.data_realizada<=v.end),ex=period.filter(x=>x.tipo==='saida');let rows=[],head=[],note='',chart='';reportRecords=period;reportTitle=reports[v.report];const sum=xs=>xs.reduce((s,x)=>s+cents(x.valor),0)/100;
if(v.report==='resumo'){const t=cashTotals(base,v.start,v.end);head=['Indicador','Valor'];rows=[['Entradas recebidas',money(t.income)],['Saídas pagas (inclui faturas)',money(t.expense)],['Resultado do fluxo de caixa',money(t.income-t.expense)],['Gastos e compromissos por vencimento',money(sum(ex))]];note='Fluxo de caixa usa a data efetiva. Gastos usam o vencimento e incluem parcelas de cartão. Transferências e investimentos não são receitas ou despesas de consumo.';const b=balances(D.contas.filter(a=>!v.acc||a.id===v.acc),liveRows(),v.end);if(v.person==='all'&&!v.cat&&!v.card){const prior=new Date(v.start+'T12:00:00Z');prior.setUTCDate(prior.getUTCDate()-1);const initial=balances(D.contas.filter(a=>!v.acc||a.id===v.acc),liveRows(),prior.toISOString().slice(0,10));rows.unshift(['Saldo calculado antes do período',money(initial.reduce((s,a)=>s+a.value,0))]);rows.push(['Saldo calculado no fim do período',money(b.reduce((s,a)=>s+a.value,0))]);if(b.some(a=>!a.known)||initial.some(a=>!a.known))note+=' Saldos parciais: faltam bases iniciais válidas para a data.';}const startDate=new Date(v.start+'T12:00:00Z'),endDate=new Date(v.end+'T12:00:00Z'),days=Math.round((endDate-startDate)/864e5)+1;const prevEnd=new Date(+startDate-864e5),prevStart=new Date(+startDate-days*864e5);const previous=cashTotals(base,prevStart.toISOString().slice(0,10),prevEnd.toISOString().slice(0,10));rows.push(['Entradas no período anterior equivalente',money(previous.income)],['Saídas no período anterior equivalente',money(previous.expense)]);let months=[];for(let m=v.start.slice(0,7);m<=v.end.slice(0,7)&&months.length<120;m=monthShift(m,1)){const ct=cashTotals(base,m+'-01'>v.start?m+'-01':v.start,monthEnd(m)<v.end?monthEnd(m):v.end);months.push({m,...ct});}const max=Math.max(1,...months.flatMap(x=>[x.income,x.expense]));chart='<div class="chart-legend"><span><i class="income-key"></i>Entradas</span><span><i class="expense-key"></i>Saídas pagas</span></div>'+months.map(x=>`<div class="chart-caption">${escape(monthName(x.m))}</div>${bar(x.income,max,'income')}${bar(x.expense,max,'expense')}`).join('');reportRecords=done;}
if(v.report==='categorias'){head=['Categoria / subcategoria','Comprometido','Participação'];const groups=new Map();for(const x of ex){const name=category(x.categoria_id)+(x.subcategoria_id?' / '+(D.fin_subcategorias.find(s=>s.id===x.subcategoria_id)?.nome||''):'');groups.set(name,(groups.get(name)||0)+cents(x.valor));}const total=sum(ex);rows=[...groups].sort((a,b)=>b[1]-a[1]).map(([name,val])=>[name,money(val/100),total?`${(val/100/total*100).toFixed(1)}%`:'0%']);chart=[...groups].map(([name,val])=>`<div class="chart-caption">${escape(name)}</div>${bar(val/100,Math.max(total,1),'expense')}`).join('');note='Gastos por vencimento, pagos e pendentes, incluindo parcelas de cartão. Pagamento de fatura é excluído para evitar duplicidade.';reportRecords=ex;}
if(v.report==='pessoas'){head=['Identificação','Gastos e parcelas','Entradas recebidas'];rows=[...D.pessoas,{id:null,nome:'Família'}].filter(p=>v.person==='all'||(p.id||'')===v.person).map(p=>[p.nome,money(sum(ex.filter(x=>x.pessoa_id===p.id))),money(sum(done.filter(x=>x.tipo==='entrada'&&x.pessoa_id===p.id)))]);note='A identificação indica de quem é o gasto ou recebimento. Não representa cobrança ou reembolso entre vocês.';}
if(v.report==='faturas'){head=['Cartão','Fatura','Compras / parcelas','Pago','Em aberto'];const filtered=invoices(liveRows()).filter(g=>g.month>=v.start.slice(0,7)&&g.month<=v.end.slice(0,7)&&(!v.card||g.cartao_id===v.card));rows=filtered.map(g=>[cardName(g.cartao_id),monthName(g.month),money(v.person==='all'&&!v.cat?g.gross:sum(g.items.filter(x=>(v.person==='all'||(x.pessoa_id||'')===v.person)&&(!v.cat||x.categoria_id===v.cat)))),v.person==='all'&&!v.cat?money(g.paid):'—',v.person==='all'&&!v.cat?money(g.remaining):'—']);note='Por pessoa ou categoria, mostramos somente as compras atribuídas. O pagamento é da fatura inteira; não há rateio entre vocês. O filtro Conta não se aplica às compras no cartão.';reportRecords=period.filter(x=>x.cartao_id);}
if(v.report==='vencimentos'){head=['Vencimento','Descrição','De quem é','Tipo','Valor','Situação'];const pending=period.filter(x=>x.status==='pendente'&&x.forma!=='credito');rows=pending.sort((a,b)=>a.data_prevista.localeCompare(b.data_prevista)).map(x=>[labelDate(x.data_prevista),x.descricao,scope(x.pessoa_id),typeNames[x.tipo],money(x.valor),x.data_prevista<today()?'Atrasado':'Previsto']);for(const g of invoices(liveRows())){const c=D.cartoes.find(c=>c.id===g.cartao_id),dt=dayInMonth(g.month,c?.dia_vencimento||10);if(g.remaining>0&&dt>=v.start&&dt<=v.end&&(!v.card||v.card===g.cartao_id)&&v.person==='all'&&!v.cat&&!v.acc)rows.push([labelDate(dt),'Fatura '+cardName(g.cartao_id),'Família','Fatura',money(Math.max(0,g.remaining-g.planned)),dt<today()?'Atrasada':'Prevista']);}note='Mostra pendências no intervalo. Faturas entram pelo saldo em aberto, descontando pagamentos já agendados para não somar duas vezes. Use uma data inicial anterior para incluir atrasados.';reportRecords=pending;}
if(v.report==='projecao'){head=['Mês','Saldo inicial projetado','Variação prevista','Saldo final projetado'];const accounts=D.contas.filter(a=>!v.acc||a.id===v.acc),ids=new Set(accounts.map(a=>a.id));let value=balances(accounts,liveRows()).reduce((s,a)=>s+a.value,0),ms=v.start.slice(0,7)<today().slice(0,7)?today().slice(0,7):v.start.slice(0,7);const pending=liveRows().filter(x=>x.status==='pendente'&&x.forma!=='credito'),groups=invoices(liveRows());let months=[];for(let m=today().slice(0,7);m<=v.end.slice(0,7)&&months.length<120;m=monthShift(m,1)){const start=value;const change=pending.filter(x=>(x.data_prevista<today()?today():x.data_prevista).slice(0,7)===m).reduce((s,x)=>s+accounts.reduce((n,a)=>n+deltaForProjection(x,a.id),0),0)/100;let invoiceDebt=0;if(!v.acc)invoiceDebt=groups.filter(g=>(g.month<today().slice(0,7)?today().slice(0,7):g.month)===m).reduce((s,g)=>s+Math.max(0,g.remaining-g.planned),0);value+=change-invoiceDebt;months.push(m);if(m>=ms)rows.push([monthName(m),money(start),money(change-invoiceDebt),money(value)]);}note='Estimativa a partir do saldo de hoje e dos compromissos conhecidos. Atrasados são considerados no mês atual. Por conta, faturas ainda sem conta de pagamento definida não são descontadas. Pessoa, categoria e cartão não alteram a projeção consolidada. Não é garantia de saldo futuro.';if(balances(accounts,liveRows()).some(a=>!a.known))note+=' Há contas sem saldo inicial: projeção parcial.';reportRecords=pending;}
if(v.report==='orcamento'){head=['Mês','Categoria','Orçamento','Comprometido','Restante'];rows=D.fin_orcamentos.filter(b=>b.mes>=v.start.slice(0,7)+'-01'&&b.mes<=v.end&&(!v.cat||b.categoria_id===v.cat)).map(b=>{const used=sum(base.filter(x=>x.tipo==='saida'&&x.data_prevista.slice(0,7)===b.mes.slice(0,7)&&x.categoria_id===b.categoria_id));return [monthName(b.mes.slice(0,7)),category(b.categoria_id),money(b.valor),money(used),money(Number(b.valor)-used)];});note='Orçamento é da categoria para a família inteira. Filtros de pessoa, conta ou cartão restringem apenas o comprometido, não o orçamento.';reportRecords=ex;}
if(v.report==='extrato'){head=['Data','Conta','Descrição','Variação','Saldo após'];const accs=D.contas.filter(a=>!v.acc||a.id===v.acc);for(const a of accs){const records=liveRows().filter(x=>x.status==='concluido'&&x.data_realizada>=v.start&&x.data_realizada<=v.end&&(!a.data_saldo_inicial||x.data_realizada>=a.data_saldo_inicial)&&deltaForProjection(x,a.id)!==0).sort((x,y)=>x.data_realizada.localeCompare(y.data_realizada)||x.criado_em.localeCompare(y.criado_em));const prior=new Date(v.start+'T12:00:00Z');prior.setUTCDate(prior.getUTCDate()-1);const baselineInside=a.data_saldo_inicial&&a.data_saldo_inicial>=v.start&&a.data_saldo_inicial<=v.end;let val=baselineInside?Number(a.saldo_inicial||0):balances([a],liveRows(),prior.toISOString().slice(0,10))[0].value;rows.push([labelDate(baselineInside?a.data_saldo_inicial:v.start),a.nome,baselineInside?'Saldo inicial cadastrado':'Saldo anterior','—',money(val)]);for(const x of records){const amount=deltaForProjection(x,a.id)/100;val+=amount;rows.push([labelDate(x.data_realizada),a.nome,x.descricao,money(amount),money(val)]);}}note='Extrato de movimentações efetivas, incluindo transferências e investimentos. Para manter o saldo consistente, filtros de pessoa, categoria e cartão não restringem o extrato. Cadastre o saldo inicial para obter saldos completos.';reportRecords=done;}
if(v.report==='objetivos'){head=['Objetivo','De quem é','Meta','Reservado até a data','Falta','Aportes no período','Retiradas no período'];const rs=reserves(liveRows(),v.end);rows=D.fin_metas.filter(g=>v.person==='all'||(g.pessoa_id||'')===v.person).map(g=>{const saved=rs.filter(r=>r.meta_id===g.id&&(!v.acc||r.conta_id===v.acc)).reduce((s,r)=>s+r.value,0),mov=done.filter(x=>x.meta_id===g.id);return [g.nome,scope(g.pessoa_id),money(g.valor_alvo),money(saved),money(Math.max(0,Number(g.valor_alvo)-saved)),money(sum(mov.filter(x=>['aporte','reserva'].includes(x.tipo)))),money(sum(mov.filter(x=>['resgate','liberacao'].includes(x.tipo))))];});note='Reservado é parte do patrimônio já existente, não um saldo adicional. Aportes e retiradas consideram somente eventos realizados no período.';reportRecords=done.filter(x=>x.meta_id);}
if(v.report==='investimentos'){head=['Data','Operação','Descrição','Origem','Destino','Objetivo','Valor'];const mov=done.filter(x=>['aporte','resgate','rendimento','perda','reserva','liberacao'].includes(x.tipo));rows=mov.map(x=>[labelDate(x.data_realizada),typeNames[x.tipo],x.descricao,account(x.conta_id),account(x.destino_id),D.fin_metas.find(g=>g.id===x.meta_id)?.nome||'Sem objetivo',money(x.valor)]);note='Aplicações e resgates não são receita ou despesa de consumo. Rendimentos e perdas são separados dos aportes; dados informados manualmente.';reportRecords=mov;}
reportRows=rows;reportHeaders=head;$('report-title').textContent=reportTitle;$('report-note').textContent=`${labelDate(v.start)} a ${labelDate(v.end)}. ${note}`;$('report-charts').innerHTML=chart;$('report-head').innerHTML='<tr>'+head.map(x=>'<th>'+escape(x)+'</th>').join('')+'</tr>';$('report-body').innerHTML=rows.length?rows.map(r=>'<tr>'+r.map(c=>'<td>'+escape(c)+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${head.length}">Nenhum registro para os filtros selecionados.</td></tr>`;}
function deltaForProjection(m,id){if(m.forma==='credito'||['reserva','liberacao'].includes(m.tipo))return 0;const v=cents(m.valor);if(['transferencia','aporte','resgate'].includes(m.tipo))return (m.destino_id===id?v:0)-(m.conta_id===id?v:0);if(m.conta_id!==id)return 0;return ['entrada','rendimento'].includes(m.tipo)?v:-v;}
function bar(value,max,type){return `<div class="barline"><div class="bartrack" aria-hidden="true"><div class="barfill bar-${type}" style="width:${Math.max(0,Math.min(100,value/max*100))}%"></div></div><span>${money(value)}</span></div>`;}
function exportCSV(){const cell=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const content='\ufeff'+[reportHeaders,...reportRows].map(r=>r.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='relatorio-financeiro-'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function newEntry(preset={}){const old=$('entry-form');if(old)old.remove();modal('Novo lançamento','<div id="modal-entry"></div>');entryForm($('modal-entry'),preset);}
async function handleAction(action,id){if(busy)return;const m=D.fin_movimentos.find(x=>x.id===id);switch(action){
case 'assistant':page='assistant';render();break;case 'goals':page='goals';render();break;case 'compare':page='reports';render();break;case 'report-visual':page='reports';render();break;case 'report-tables':renderDetailedReports();$('view').insertAdjacentHTML('afterbegin','<div class=toolbar>'+button('report-visual','Voltar aos gráficos')+'</div>');break;case 'assistant-review':{const d=assistantDrafts[Number(id)];if(d&&!d.saved)newEntry({...d.draft,__assistant:true,__index:Number(id)});break;}case 'cards-update':showCardsUpdate();break;case 'verify-cards':await load();if(schemaCards){$('modal').close();$('global-message').textContent='Atualização ativada.';}else $('modal-message').textContent='A atualização ainda não foi encontrada. Verifique as migrações no EasyPanel.';break;case 'charge':if(!schemaCards){showCardsUpdate();break;}if(m){modal('Confirmar cobrança',simpleForm(`<p class="full">Confirme somente se esta cobrança já apareceu no cartão: ${escape(m.descricao)} · ${money(m.valor)}. Em compras parceladas, confirma toda a compra.</p>`,'A cobrança já ocorreu'));bindSimple(()=>rpc('fin_confirmar_cobranca',{p_id:id,p_efetivada:true}));}break;case 'delete':if(!schemaCards){showCardsUpdate();break;}if(m){modal('Excluir definitivamente',simpleForm(`<p class="full">${escape(m.descricao)} · ${money(m.valor)}</p><p class="full pill-warning">O lançamento será removido das movimentações e dos cálculos. Esta ação não é um cancelamento. Excluir movimentos de uma reserva pode exigir liberar primeiro o valor do objetivo.</p>`+select('escopo','O que excluir?',dictOpts({somente:'Somente este lançamento',...(m.plano_id?{proximos:'Este e os próximos da série',serie:'Toda a série'}:{})},'somente'),true),'Excluir definitivamente'));bindSimple(()=>rpc('fin_excluir',{p_id:id,p_escopo:$('simple-form').elements.escopo.value}));}break;case 'refresh':await load();break;case 'new':newEntry();break;case 'transfer':newEntry({tipo:'transferencia'});break;case 'new-credit':newEntry({tipo:'saida',forma:'credito'});break;case 'pay-invoice':newEntry({tipo:'pagamento_fatura'});break;case 'pay-specific':{const [c,month]=id.split('|'),g=invoices(liveRows()).find(g=>g.cartao_id===c&&g.month===month);newEntry({tipo:'pagamento_fatura',cartao_id:c,fatura_mes:month,valor:g.remaining,descricao:'Pagamento de fatura '+cardName(c)});break;}
case 'invest':newEntry({tipo:'aporte'});break;case 'reserve':newEntry({tipo:'reserva'});break;case 'redeem':newEntry({tipo:'resgate'});break;case 'yield':newEntry({tipo:'rendimento'});break;case 'loss':newEntry({tipo:'perda'});break;case 'goal-add':newEntry({tipo:'reserva',meta_id:id,descricao:'Reserva para '+D.fin_metas.find(g=>g.id===id)?.nome});break;case 'goal-release':newEntry({tipo:'liberacao',meta_id:id});break;
case 'account-new':configAccount();break;case 'investment-account':configAccount('','investimento');break;case 'account-edit':configAccount(id);break;case 'card-new':configCard();break;case 'card-edit':configCard(id);break;case 'goal-new':configGoal();break;case 'goal-edit':configGoal(id);break;case 'budget-new':configBudget();break;case 'budget-edit':configBudget(id);break;case 'category-new':configCategory();break;case 'category-edit':configCategory(id);break;case 'subcategory-new':configCategory('',id,true);break;case 'subcategory-edit':configCategory(id,'',true);break;
case 'duplicate':if(m)newEntry({...m,pagador:payerFor(m),id:undefined,data_prevista:today(),data_realizada:today(),status:'pendente',fatura_mes:null,descricao:m.descricao});break;
case 'settle':if(m){modal(m.tipo==='entrada'?'Confirmar recebimento':'Confirmar movimentação',simpleForm(`<p class="full">${escape(m.descricao)} · ${money(m.valor)}</p>`+input('date','Data efetiva','date',today(),`required max="${today()}"`)+select('conta_id','Conta utilizada',opts(D.contas.filter(a=>a.ativa),m.conta_id),true)));bindSimple(async v=>{if(!v.conta_id)throw Error('Selecione a conta.');reserveCheck({...m,conta_id:v.conta_id,status:'concluido'},Number(m.valor));const r=await save('fin_movimentos',{status:'concluido',data_realizada:v.date,conta_id:v.conta_id},m.id);if(!r?.length)throw Error('A alteração não foi confirmada.');});}break;
case 'edit':if(m){modal('Editar lançamento',simpleForm(input('descricao','Descrição','text',m.descricao,'required',true)+input('valor','Valor desta ocorrência','text',m.valor,'required inputmode="decimal"')+select('pessoa_id','De quem é?',scopeOptions(m.pessoa_id))+input('data',m.forma==='credito'?'Vencimento da parcela / fatura':'Data prevista','date',m.data_prevista,'required')+(schemaCards?input('compra',m.forma==='credito'?'Data original da compra':'Data do lançamento','date',purchaseDate(m,D)||'','required'):'')+(m.status==='concluido'?input('real','Data efetiva','date',m.data_realizada,`required max="${today()}"`):'')+(m.categoria_id?select('categoria_id','Categoria',opts(D.categorias.filter(c=>c.tipo===m.tipo),m.categoria_id))+select('subcategoria_id','Subcategoria',opts(D.fin_subcategorias.filter(x=>x.categoria_id===m.categoria_id),m.subcategoria_id,'Sem subcategoria')):'')+select('futuras','Aplicar em',dictOpts({nao:'Somente este lançamento',...(m.plano_id&&m.status==='pendente'?{sim:'Este e os futuros pendentes'}:{})},'nao'),true)+'<p class="full small">Nas futuras, as datas permanecem iguais. Alterar o valor de uma parcela muda o total da compra. Histórico realizado não é alterado em lote.</p>'));bindSimple(v=>rpc(schemaCards?'fin_editar_compra':'fin_editar',{...(schemaCards?{p_compra:v.compra}:{}),p_id:m.id,p_futuras:v.futuras==='sim',p_descricao:v.descricao.trim(),p_valor:parseValue(v.valor),p_pessoa:v.pessoa_id||null,p_categoria:v.categoria_id||null,p_subcategoria:v.subcategoria_id||null,p_data:v.data,p_real:v.real||null}));const cf=$('simple-form').elements.categoria_id;if(cf)cf.onchange=()=>{$('simple-form').elements.subcategoria_id.innerHTML=opts(D.fin_subcategorias.filter(x=>x.categoria_id===cf.value),'','Sem subcategoria');};}break;
case 'cancel':if(m){modal('Cancelar lançamento',simpleForm(`<p class="full">${escape(m.descricao)} · ${money(m.valor)}</p><p class="full pill-warning">O registro ficará cancelado e deixará de participar dos totais. Se já estiver realizado, seu efeito no saldo será desfeito. O histórico continuará disponível.</p>`+select('futuras','Cancelar',dictOpts({nao:'Somente este lançamento',...(m.plano_id&&m.status==='pendente'?{sim:'Este e os futuros pendentes'}:{})},'nao'),true),'Confirmar cancelamento'));bindSimple(v=>rpc('fin_cancelar',{p_id:m.id,p_futuras:v.futuras==='sim'}));}break;
case 'reconcile':{const a=balances(D.contas,liveRows()).find(x=>x.id===id);modal('Conferir saldo',simpleForm(`<p class="full">${escape(a.nome)} · calculado: <b>${money(a.value)}</b></p>`+input('actual','Saldo mostrado pelo banco hoje','text','','required inputmode="decimal"',true)+'<div id="balance-difference" class="full"></div>','Conferir'));$('simple-form').onsubmit=e=>{e.preventDefault();const s=e.target.elements.actual.value;if(!/^-?\d+([,.]\d{1,2})?$/.test(s)){$('modal-message').textContent='Informe um saldo válido.';return;}const difference=Number(s.replace(',','.'))-a.value;$('balance-difference').innerHTML=`<p class="${Math.abs(difference)>.005?'pill-warning':'positive'}">Diferença: ${money(difference)}. ${Math.abs(difference)>.005?'Confira o saldo inicial e os lançamentos no extrato. Nenhum ajuste foi feito automaticamente.':'Os saldos conferem.'}</p>${button('account-statement','Abrir extrato',id)}`;};break;}
case 'account-statement':page='reports';$('modal').close();renderDetailedReports();document.querySelector('[name=report]').value='extrato';document.querySelector('[name=acc]').value=id;updateReport();break;
case 'due-report':page='reports';renderDetailedReports();document.querySelector('[name=report]').value='vencimentos';document.querySelector('[name=start]').value='2000-01-01';document.querySelector('[name=end]').value=new Date(Date.now()+30*864e5).toISOString().slice(0,10);updateReport();break;
case 'csv':exportCSV();break;case 'print':window.print();break;case 'report-detail':modal('Lançamentos do relatório',movementList([...reportRecords]));break;

}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action,b.dataset.id).catch(err=>{$('global-message').textContent=textError(err);if($('modal').open)$('modal-message').textContent=textError(err);});});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_financial_entry',title:'Preparar lançamento',description:'Abre o formulário financeiro para revisão e confirmação humana. Não grava valores.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Não são aceitos parâmetros.');if(!family||!session)throw Error('Faça login primeiro.');newEntry();return {formulario_aberto:true,salvo:false};}})).catch(()=>{});}catch{}}

let dashboardPerson='all',assistantDrafts=[],assistantText='';
const payerFor=m=>D.fin_planos?.find(p=>p.id===m.plano_id)?.dados?.pagador||'';
function navIcon(id){if(id==='assistant')return '<img class="north-nav-compass" src="assets/north-compass-light.svg" width="20" height="20" alt="">';const paths={overview:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',assistant:'M4 4h16v12H9l-5 4Z',entries:'M4 7h16M16 3l4 4-4 4M20 17H4m4-4-4 4 4 4',cards:'M3 5h18v14H3ZM3 10h18',accounts:'M3 8 12 3l9 5M5 10v8m7-8v8m7-8v8M3 21h18',goals:'M21 12a9 9 0 1 1-9-9m0 4a5 5 0 1 0 5 5m-5 0 9-9',budgets:'M4 4h16v16H4ZM8 8h8M8 12h8M8 16h4',reports:'M5 20V10m7 10V4m7 16v-7',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6m-8 0v6'};return `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.overview}"/></svg>`;}
async function stableId(text){const bytes=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)));bytes[6]=(bytes[6]&15)|80;bytes[8]=(bytes[8]&63)|128;const h=[...bytes.slice(0,16)].map(x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;}
async function ensureCategories(){
 const catalog=defaultCategories;
 const categories=[],subs=[],linked=[];
 for(const [tipo,nome,subnames] of catalog){const id=await stableId(family.id+'|categoria|'+tipo+'|'+norm(nome));let c=D.categorias.find(c=>c.familia_id===family.id&&(c.id===id||(c.tipo===tipo&&norm(c.nome)===norm(nome))));if(!c){c={id,familia_id:family.id,tipo,nome,ativa:true};categories.push(c);}linked.push([c,subnames]);}
 const insert=async(table,rows)=>{if(!rows.length)return;await request('/rest/v1/'+table+'?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates'},body:JSON.stringify(rows)});};
 await insert('categorias',categories);if(categories.length)D.categorias=await all('categorias');
 for(const [c,names] of linked){for(const nome of names){const id=await stableId(family.id+'|sub|'+c.id+'|'+norm(nome));if(!D.fin_subcategorias.some(s=>s.id===id||(s.categoria_id===c.id&&norm(s.nome)===norm(nome))))subs.push({id,familia_id:family.id,categoria_id:c.id,nome});}}
 await insert('fin_subcategorias',subs);if(subs.length)D.fin_subcategorias=await all('fin_subcategorias');
}
function renderReports(){ $('view').innerHTML='<div class="toolbar">'+button('report-tables','Relatórios detalhados e exportação','','outline')+'</div><div id="visual-reports"></div>';mountAnalytics($('visual-reports'),{D,rows:liveRows(),month:$('month').value,initialPerson:dashboardPerson,scopeName:scope,categoryName:category,showRecords:rows=>modal('Lançamentos do gráfico',movementList([...new Map(rows.map(r=>[r.id,r])).values()]))});}
const chatState={messages:[],queue:[],index:0,saved:[],busy:false,confirm:false,error:null};
async function refreshConversation(){const [rows,plans]=await Promise.all([all('fin_movimentos'),all('fin_planos')]);D.fin_movimentos=rows;D.fin_planos=plans;}
function renderAssistant(){
 mountConversation($('view'),{state:chatState,getData:()=>D,currentPerson:()=>me.id,createRecord:(kind,d)=>createInlineRecord({kind,type:d.tipo,parent:d.categoria_id,accountType:d.forma==='dinheiro'?'dinheiro':'bancaria',getData:()=>D,save}),
 saveDraft:async item=>{const v=item.draft;const body={...v,valor:Number(v.valor),pessoa_id:v.pessoa_id||null,fatura_mes:v.fatura_mes?v.fatura_mes+'-01':null};const result=await rpc('fin_criar',{p_id:item.id,p_familia:family.id,p_modalidade:v.modalidade,p_inicio:v.data_prevista,p_fim:null,p_frequencia:v.frequencia||'mensal',p_quantidade:v.modalidade==='parcelado'?Number(v.quantidade):1,p_dados:body});if(result!==item.id)throw Error('Não foi possível confirmar o lançamento. Tente novamente.');},
 undoPlans:async item=>{await request('/rest/v1/fin_planos?id=eq.'+item.id+'&familia_id=eq.'+family.id,{method:'PATCH',body:JSON.stringify({ativo:false})});const result=await request('/rest/v1/fin_movimentos?plano_id=eq.'+item.id+'&familia_id=eq.'+family.id,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({status:'cancelado',data_realizada:null})});if(!result?.length)throw Error('Nenhum lançamento foi encontrado para desfazer. Atualize o painel.');},
 editRecord:async item=>{const v=item.draft,credit=v.forma==='credito',c=D.cartoes.find(c=>c.id===v.cartao_id);const result=await save('fin_movimentos',{descricao:v.descricao,valor:Number(v.valor),pessoa_id:v.pessoa_id||null,categoria_id:v.categoria_id||null,subcategoria_id:v.subcategoria_id||null,forma:v.forma,conta_id:credit?null:v.conta_id,cartao_id:credit||v.tipo==='pagamento_fatura'?v.cartao_id:null,...(schemaCards?{data_compra:v.data_prevista}:{}),data_prevista:credit?dayInMonth(v.fatura_mes,c.dia_vencimento):v.data_prevista,status:v.status,data_realizada:v.data_realizada||null,fatura_mes:v.fatura_mes?v.fatura_mes+'-01':null},item.editId);if(!result?.length)throw Error('A correção não foi confirmada.');},refreshData:refreshConversation});
}

